"""Citation Validation Pipeline for Stage 127 AI Research (Part XL, XLI & XLII).

Server-authoritative verification of all citations in generated answers.
Rejects fabricated citation IDs (Fixture E) and unsupported quotes.
"""

from __future__ import annotations

import re
from typing import Dict, List, Set, Tuple

from atlas.ai.research.domain import CitationValidationStatus, ResearchCitation, ResearchEvidence


class CitationValidator:
    """Validates citations generated by LLM turns against authorized evidence."""

    @staticmethod
    def extract_and_validate_citations(
        answer_text: str,
        retrieved_evidence: List[ResearchEvidence],
    ) -> Tuple[str, List[ResearchCitation]]:
        """Parses citation tokens from answer text, verifies against real evidence,

        and strips or marks fabricated citations.

        Returns:
            (sanitized_answer_text, validated_citations_list)
        """
        evidence_map: Dict[str, ResearchEvidence] = {
            ev.evidence_id: ev for ev in retrieved_evidence
        }
        # Also map chunk_ids
        for ev in retrieved_evidence:
            evidence_map[ev.chunk_id] = ev

        validated_citations: List[ResearchCitation] = []
        rejected_citation_tokens: Set[str] = set()

        # Match tokens like [cite:ev_...], [Source ev_...], [Source 999], [Source: doc_...]
        cite_pattern = re.compile(
            r"\[(?:cite:|Source\s*#?|Source:\s*)([a-zA-Z0-9_\-]+)\]",
            re.IGNORECASE,
        )

        for match in cite_pattern.finditer(answer_text):
            raw_token = match.group(0)
            target_id = match.group(1).strip()

            # Check if target_id matches a known evidence unit
            matched_ev = evidence_map.get(target_id)
            if not matched_ev:
                # Check if it was written without 'ev_' prefix e.g. target_id = chk_...
                matched_ev = evidence_map.get(f"ev_{target_id}")

            if matched_ev:
                citation_id = f"cite_{matched_ev.evidence_id}"
                citation = ResearchCitation(
                    citation_id=citation_id,
                    evidence_id=matched_ev.evidence_id,
                    document_id=matched_ev.document_id,
                    symbol=matched_ev.symbol,
                    title=matched_ev.title,
                    page_number=matched_ev.page_number,
                    section_title=matched_ev.section_title,
                    publication_date=matched_ev.publication_date,
                    claim_text=matched_ev.exact_span,
                    quote_span=matched_ev.exact_span[:150],
                    status=CitationValidationStatus.VERIFIED,
                )
                if not any(c.citation_id == citation.citation_id for c in validated_citations):
                    validated_citations.append(citation)
            else:
                # Fabricated Citation (Fixture E)!
                rejected_citation_tokens.add(raw_token)
                fake_cite = ResearchCitation(
                    citation_id=f"cite_invalid_{target_id}",
                    evidence_id=target_id,
                    document_id="UNKNOWN",
                    title="Fabricated or Missing Source",
                    page_number=0,
                    section_title="Unknown",
                    publication_date="",
                    claim_text="",
                    quote_span="",
                    status=CitationValidationStatus.REJECTED,
                    validation_reason=f"Source ID '{target_id}' does not exist in authorized evidence.",
                )
                validated_citations.append(fake_cite)

        # Sanitize answer text: strip rejected fabricated tokens from final user-facing text
        clean_answer = answer_text
        for bad_token in rejected_citation_tokens:
            clean_answer = clean_answer.replace(bad_token, "")

        # Clean up any duplicate spacing created by stripping bad tokens
        clean_answer = re.sub(r"[ \t]+", " ", clean_answer).strip()

        return clean_answer, validated_citations
